"""Раздел 4. Методика сравнительной оценки электрического и дизельного тракторов."""
import numpy as np

from models import AHP_GROUPS, CRITERIA, GROUPS
from repdata import FIG, f, pc


def frac(x):
    for n, s in ((1, "1"), (2, "2"), (3, "3"), (0.5, "1/2"), (1 / 3, "1/3")):
        if abs(x - n) < 1e-9:
            return s
    return f(x, 2)


